package knowledge

import (
	"crypto/sha256"
	"fmt"
	"os"
	"path/filepath"
	"testing"
)

// source-oracle.json must be generated by the actual TypeScript source script.
// Missing output fails rather than claiming differential coverage through skips.
func TestActualSourceOracle(t *testing.T) {
	raw, e := os.ReadFile("testdata/source-oracle.json")
	must(t, e)
	fixture := parse(t, string(raw))
	for _, m := range object(get(fixture, "sources")).Members() {
		b, e := os.ReadFile(filepath.Join("../../..", m.Key))
		must(t, e)
		if fmt.Sprintf("%x", sha256.Sum256(b)) != m.Value {
			t.Fatalf("stale source %s", m.Key)
		}
	}
	for _, v := range arr(get(fixture, "schema")) {
		t.Run("schema/"+str(get(v, "name")), func(t *testing.T) {
			parsed, err := parseEdge(object(get(v, "edge")))
			if (err == nil) != (get(v, "valid") == true) {
				t.Fatal("schema result", err)
			}
			if err == nil && jsonText(t, parsed) != get(v, "canonical") {
				t.Fatalf("canonical schema differs: %s vs %v", jsonText(t, parsed), get(v, "canonical"))
			}
		})
	}
	for _, v := range arr(get(fixture, "cases")) {
		t.Run(str(get(v, "name")), func(t *testing.T) {
			rows := []*Object{}
			for _, row := range arr(get(v, "input")) {
				rows = append(rows, object(clone(row)))
			}
			storage := &oracleStorage{rows: rows, effects: []any{}}
			l := &Lifecycle{storage}
			op := get(v, "op")
			var err error
			if get(op, "kind") == "assertion" {
				err = l.PurgeAssertion(str(get(op, "id")))
			} else {
				err = l.PurgeSource(str(get(op, "scene")), str(get(op, "message")))
			}
			if (err != nil) != has(v, "error") {
				t.Fatalf("error mismatch: %v, source %v", err, get(v, "error"))
			}
			out := []any{}
			for _, row := range storage.rows {
				out = append(out, row)
			}
			if !deepEqual(out, get(v, "rows")) {
				t.Fatalf("rows differ\nGo %s\nTS %s", jsonText(t, out), jsonText(t, get(v, "rows")))
			}
			if !deepEqual(storage.effects, get(v, "effects")) {
				t.Fatalf("effects differ\nGo %s\nTS %s", jsonText(t, storage.effects), jsonText(t, get(v, "effects")))
			}
		})
	}
}

type oracleStorage struct {
	rows    []*Object
	effects []any
}

func (s *oracleStorage) RequireTransaction() error                         { return nil }
func (s *oracleStorage) Rows(scene *string, limit *int) ([]*Object, error) { return s.rows, nil }
func (s *oracleStorage) Remove(id string) error {
	s.effects = append(s.effects, obj("kind", "remove", "id", id))
	for i, row := range s.rows {
		if get(row, "id") == id {
			s.rows = append(s.rows[:i], s.rows[i+1:]...)
			break
		}
	}
	return nil
}
func (s *oracleStorage) Replace(edge *Object) error {
	s.effects = append(s.effects, obj("kind", "replace", "edge", edge))
	for i, row := range s.rows {
		if get(row, "id") == get(edge, "id") {
			s.rows[i] = edge
			break
		}
	}
	return nil
}
